SELECT (SELECT group_concat(x, ',') FROM (SELECT x FROM t1 ORDER BY x)), (SELECT group_concat(y||':'||z, ',') FROM (SELECT y,z FROM t2 ORDER BY y)), (SELECT group_concat(u||':'||v, ',') FROM (SELECT u,v FROM t3 ORDER BY u)), (SELECT count(*) FROM sqlite_schema WHERE type='table' AND name IN ('t1','t2','t3')), (SELECT count(*) FROM sqlite_schema WHERE type='index' AND name IN ('t2z','t3v'));